import { useFocusEffect } from '@react-navigation/native';
import { useCallback, useState } from 'react';
import { Pressable, StyleSheet, Text, View } from 'react-native';

import ExpoHealthBench from '../modules/expo-health-bench/src/ExpoHealthBenchModule';
import type {
  DayStepEntry,
  HealthAuthorizationStatus,
} from '../modules/expo-health-bench/src/ExpoHealthBench.types';

const STATUS_LABELS: Record<HealthAuthorizationStatus, string> = {
  notDetermined: 'Health access: not requested',
  authorized: 'Health access: granted',
  denied: 'Health access: denied',
};

function formatDayLabel(startOfDayMillis: number): string {
  const date = new Date(startOfDayMillis);
  const weekday = date.toLocaleDateString('en-US', { weekday: 'short' });
  const month = date.toLocaleDateString('en-US', { month: 'short' });
  return `${weekday} ${month} ${date.getDate()}`;
}

function isToday(startOfDayMillis: number): boolean {
  const date = new Date(startOfDayMillis);
  const now = new Date();
  return (
    date.getFullYear() === now.getFullYear() &&
    date.getMonth() === now.getMonth() &&
    date.getDate() === now.getDate()
  );
}

function messageFromError(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

export default function HealthScreen() {
  const [status, setStatus] = useState<HealthAuthorizationStatus>('notDetermined');
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [days, setDays] = useState<DayStepEntry[] | null>(null);
  const [isLogging, setIsLogging] = useState(false);

  const loadDays = useCallback(async () => {
    try {
      const result = await ExpoHealthBench.getLast7DaysSteps();
      setDays(result);
    } catch (error) {
      setErrorMessage(messageFromError(error));
    }
  }, []);

  useFocusEffect(
    useCallback(() => {
      (async () => {
        try {
          const current = await ExpoHealthBench.getAuthorizationStatus();
          setStatus(current);
          setErrorMessage(null);
          if (current === 'authorized') {
            await loadDays();
          }
        } catch (error) {
          setErrorMessage(messageFromError(error));
        }
      })();
    }, [loadDays])
  );

  const handleRequestAccess = async () => {
    try {
      const result = await ExpoHealthBench.requestAuthorization();
      setStatus(result);
      setErrorMessage(null);
      if (result === 'authorized') {
        await loadDays();
      }
    } catch (error) {
      setErrorMessage(messageFromError(error));
    }
  };

  const handleLogSteps = async () => {
    setIsLogging(true);
    try {
      await ExpoHealthBench.logSteps(500);
      setErrorMessage(null);
      await loadDays();
    } catch (error) {
      setErrorMessage(messageFromError(error));
    } finally {
      setIsLogging(false);
    }
  };

  const canLog = status === 'authorized' && !isLogging;
  const statusLine = errorMessage ?? STATUS_LABELS[status];

  return (
    <View style={styles.container}>
      <Text style={styles.status}>{statusLine}</Text>

      <View style={styles.buttons}>
        <Pressable style={styles.button} onPress={handleRequestAccess}>
          <Text style={styles.buttonText}>Request Access</Text>
        </Pressable>
        <Pressable
          style={[styles.button, !canLog && styles.buttonDisabled]}
          disabled={!canLog}
          onPress={handleLogSteps}>
          <Text style={[styles.buttonText, !canLog && styles.buttonTextDisabled]}>
            Log 500 Steps
          </Text>
        </Pressable>
      </View>

      <Text style={styles.sectionHeader}>Last 7 Days</Text>

      {status !== 'authorized' ? (
        <Text style={styles.emptyState}>Health access needed</Text>
      ) : (
        days?.map((day) => {
          const today = isToday(day.startOfDayMillis);
          const stepsLabel = Math.round(day.steps).toLocaleString('en-US');
          return (
            <Text
              key={day.startOfDayMillis}
              style={[styles.dayRow, today && styles.dayRowToday]}>
              {formatDayLabel(day.startOfDayMillis)} — {stepsLabel} steps
              {today ? ' (today)' : ''}
            </Text>
          );
        })
      )}
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#fff',
    paddingHorizontal: 24,
    paddingTop: 24,
  },
  status: {
    fontSize: 16,
    color: '#333',
  },
  buttons: {
    marginTop: 20,
    gap: 12,
  },
  button: {
    backgroundColor: '#007AFF',
    borderRadius: 12,
    paddingVertical: 14,
    alignItems: 'center',
  },
  buttonDisabled: {
    backgroundColor: '#ccc',
  },
  buttonText: {
    color: '#fff',
    fontSize: 16,
    fontWeight: '600',
  },
  buttonTextDisabled: {
    color: '#888',
  },
  sectionHeader: {
    marginTop: 32,
    fontSize: 18,
    fontWeight: '700',
  },
  emptyState: {
    marginTop: 12,
    fontSize: 15,
    color: '#888',
  },
  dayRow: {
    marginTop: 10,
    fontSize: 15,
    color: '#333',
  },
  dayRowToday: {
    fontWeight: '700',
    color: '#007AFF',
  },
});

import ExpoModulesCore
import HealthKit

struct DayStepEntry: Record {
  @Field var startOfDayMillis: Double = 0
  @Field var steps: Double = 0
}

public class ExpoHealthBenchModule: Module {
  private let healthStore = HKHealthStore()
  private let stepType = HKQuantityType.quantityType(forIdentifier: .stepCount)!

  public func definition() -> ModuleDefinition {
    Name("ExpoHealthBench")

    AsyncFunction("getAuthorizationStatus") { () -> String in
      self.statusString(self.healthStore.authorizationStatus(for: self.stepType))
    }

    AsyncFunction("requestAuthorization") { (promise: Promise) in
      guard HKHealthStore.isHealthDataAvailable() else {
        promise.reject("E_HEALTHKIT_UNAVAILABLE", "Health data is not available on this device")
        return
      }
      self.healthStore.requestAuthorization(toShare: [self.stepType], read: [self.stepType]) { _, error in
        if let error = error {
          promise.reject("E_HEALTHKIT_AUTH", error.localizedDescription)
          return
        }
        promise.resolve(self.statusString(self.healthStore.authorizationStatus(for: self.stepType)))
      }
    }

    AsyncFunction("logSteps") { (count: Double, promise: Promise) in
      let now = Date()
      let quantity = HKQuantity(unit: .count(), doubleValue: count)
      let sample = HKQuantitySample(type: self.stepType, quantity: quantity, start: now, end: now)
      self.healthStore.save(sample) { success, error in
        if let error = error {
          promise.reject("E_HEALTHKIT_SAVE", error.localizedDescription)
        } else if !success {
          promise.reject("E_HEALTHKIT_SAVE", "Failed to save the step sample")
        } else {
          promise.resolve(nil)
        }
      }
    }

    AsyncFunction("getLast7DaysSteps") { (promise: Promise) in
      self.fetchLast7DaysSteps(promise: promise)
    }
  }

  private func statusString(_ status: HKAuthorizationStatus) -> String {
    switch status {
    case .sharingAuthorized:
      return "authorized"
    case .sharingDenied:
      return "denied"
    case .notDetermined:
      return "notDetermined"
    @unknown default:
      return "notDetermined"
    }
  }

  private func fetchLast7DaysSteps(promise: Promise) {
    let calendar = Calendar.current
    let startOfToday = calendar.startOfDay(for: Date())
    guard
      let rangeStart = calendar.date(byAdding: .day, value: -6, to: startOfToday),
      let rangeEnd = calendar.date(byAdding: .day, value: 1, to: startOfToday)
    else {
      promise.reject("E_HEALTHKIT_QUERY", "Failed to compute the date range")
      return
    }

    var intervalComponents = DateComponents()
    intervalComponents.day = 1

    let predicate = HKQuery.predicateForSamples(withStart: rangeStart, end: rangeEnd, options: .strictStartDate)
    let query = HKStatisticsCollectionQuery(
      quantityType: stepType,
      quantitySamplePredicate: predicate,
      options: .cumulativeSum,
      anchorDate: startOfToday,
      intervalComponents: intervalComponents
    )

    query.initialResultsHandler = { _, results, error in
      if let error = error {
        promise.reject("E_HEALTHKIT_QUERY", error.localizedDescription)
        return
      }

      var days: [DayStepEntry] = []
      results?.enumerateStatistics(from: rangeStart, to: rangeEnd) { statistics, _ in
        var entry = DayStepEntry()
        entry.startOfDayMillis = statistics.startDate.timeIntervalSince1970 * 1000
        entry.steps = statistics.sumQuantity()?.doubleValue(for: .count()) ?? 0
        days.append(entry)
      }
      days.reverse()
      promise.resolve(days)
    }

    healthStore.execute(query)
  }
}

