import { useFocusEffect } from '@react-navigation/native';
import { useCallback, useState } from 'react';
import { Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';

import ExpoSpeechBench from '../modules/expo-speech-bench/src/ExpoSpeechBenchModule';
import type { SpeechAuthorizationStatus } from '../modules/expo-speech-bench/src/ExpoSpeechBench.types';

const STATUS_LABELS: Record<SpeechAuthorizationStatus, string> = {
  notDetermined: 'Speech access: not requested',
  authorized: 'Speech access: granted',
  denied: 'Speech access: denied',
};

function messageFromError(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

export default function TranscribeScreen() {
  const [status, setStatus] = useState<SpeechAuthorizationStatus>('notDetermined');
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [isTranscribing, setIsTranscribing] = useState(false);
  const [partialText, setPartialText] = useState('');
  const [transcript, setTranscript] = useState<string | null>(null);
  const [elapsedSeconds, setElapsedSeconds] = useState<number | null>(null);

  useFocusEffect(
    useCallback(() => {
      (async () => {
        try {
          const current = await ExpoSpeechBench.getAuthorizationStatus();
          setStatus(current);
          setErrorMessage(null);
        } catch (error) {
          setErrorMessage(messageFromError(error));
        }
      })();
    }, [])
  );

  const handleRequestAccess = async () => {
    try {
      const result = await ExpoSpeechBench.requestAuthorization();
      setStatus(result);
      setErrorMessage(null);
    } catch (error) {
      setErrorMessage(messageFromError(error));
    }
  };

  const handleTranscribe = async () => {
    setIsTranscribing(true);
    setErrorMessage(null);
    setTranscript(null);
    setElapsedSeconds(null);
    setPartialText('');

    const startedAt = Date.now();
    const subscription = ExpoSpeechBench.addListener('onPartialTranscript', (event) => {
      setPartialText(event.text);
    });

    try {
      const result = await ExpoSpeechBench.transcribeSample();
      setTranscript(result);
      setElapsedSeconds((Date.now() - startedAt) / 1000);
    } catch (error) {
      setErrorMessage(messageFromError(error));
    } finally {
      subscription.remove();
      setIsTranscribing(false);
    }
  };

  const canTranscribe = status === 'authorized' && !isTranscribing;
  const statusLine = errorMessage ?? (isTranscribing ? 'Transcribing…' : STATUS_LABELS[status]);

  return (
    <View style={styles.container}>
      <Text style={styles.status}>{statusLine}</Text>

      <View style={styles.buttons}>
        <Pressable style={styles.button} onPress={handleRequestAccess}>
          <Text style={styles.buttonText}>Request Access</Text>
        </Pressable>
        <Pressable
          style={[styles.button, !canTranscribe && styles.buttonDisabled]}
          disabled={!canTranscribe}
          onPress={handleTranscribe}>
          <Text style={[styles.buttonText, !canTranscribe && styles.buttonTextDisabled]}>
            Transcribe Sample
          </Text>
        </Pressable>
      </View>

      <ScrollView style={styles.transcriptArea} contentContainerStyle={styles.transcriptContent}>
        {isTranscribing ? (
          <Text style={styles.transcriptText}>{partialText}</Text>
        ) : transcript !== null ? (
          <>
            <Text style={styles.transcriptText}>{transcript}</Text>
            {elapsedSeconds !== null ? (
              <Text style={styles.completedLine}>Completed in {elapsedSeconds.toFixed(1)} s</Text>
            ) : null}
          </>
        ) : (
          <Text style={styles.emptyState}>No transcript yet</Text>
        )}
      </ScrollView>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#fff',
    paddingHorizontal: 24,
    paddingTop: 24,
  },
  status: {
    fontSize: 16,
    color: '#333',
  },
  buttons: {
    marginTop: 20,
